project.solution:
def load_marks(path):
    marks = {}
    try:
        with open(path) as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                name, mark = line.split(",")
                try:
                    marks[name] = int(mark)
                except ValueError:
                    continue
    except FileNotFoundError:
        return {}
    return marks
